CREATE TABLE IF NOT EXISTS product_shelf_life(policy_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,product_id TEXT NOT NULL,shelf_days INTEGER NOT NULL,fefo_required BOOLEAN NOT NULL DEFAULT TRUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS batch_shelf_life(batch_life_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,product_id TEXT NOT NULL,manufactured_on DATE NOT NULL,expiry_on DATE NOT NULL,status TEXT NOT NULL DEFAULT 'VALID',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_coa(coa_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,inspection_id TEXT,coa_no TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',issued_at TIMESTAMP,issued_by TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_nutrition(product_nutrition_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,product_id TEXT NOT NULL,serving_size TEXT,energy_kcal NUMERIC,protein_g NUMERIC,carbohydrate_g NUMERIC,fat_g NUMERIC,sodium_mg NUMERIC,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS batch_allergen(batch_allergen_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,allergen_code TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'BOM',contains BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recall_impact(impact_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',affected_qty NUMERIC NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS capa_effectiveness(effectiveness_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,capa_id TEXT NOT NULL,evidence TEXT NOT NULL,effective BOOLEAN NOT NULL,verified_by TEXT NOT NULL,verified_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_batch_life_expiry ON batch_shelf_life(organization_id,entity_id,product_id,expiry_on,status);
